/* eslint-disable react/display-name */
import React from 'react';
import { Box, CardMedia } from '@mui/material';
import { API_URL } from '../../../config';

export const LabelPrint = React.forwardRef<
  HTMLDivElement,
  {
    id: string;
    width: number;
    height: number;
  }
>(({ id, width, height }, ref) => {
  return (
    <Box
      ref={ref}
    >
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justify: 'center',

        }}
      >
        <CardMedia
          alt="logo"
          component="img"
          image={`${API_URL}/Product/generate-barcode?Id=${id}`}
          sx={{
            width: '100%',
            p: 0,
            m: 0,
          }}
        />
      </Box>
    </Box>
  );
});
