/* eslint-disable react/jsx-sort-props */
import React from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  Typography,
  useMediaQuery,
} from '@mui/material';
import InfoOutlinedIcon from '@mui/icons-material/InfoOutlined';
import { IProductData } from '../../../core/Interface/product.interface';
import { theme } from '../../../theme';
import { useTranslation } from 'react-i18next';
import {
  getPriceFormat,
  formatDate,
  formatTimeToUtc,
} from '../../../core/utils';
import { appColors, HEADER_GRADIENT } from '../../../theme/appColors';

interface ProductListDataProps {
  open: boolean;
  setOpen: (open: boolean) => void;
  data?: IProductData;
  currencyCode: string;
}

const ProductListData: React.FC<ProductListDataProps> = ({
  open,
  setOpen,
  data,
  currencyCode,
}) => {
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const { t } = useTranslation(['product']);
  const handleClose = () => {
    setOpen(false);
  };

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      aria-labelledby="product-list-data-title"
      maxWidth="sm"
      fullWidth
      fullScreen={isMobile}
      PaperProps={{ sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' } }}
    >
      <DialogTitle sx={{ p: 0 }}>
        <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
          <Stack alignItems="center" direction="row" spacing={1.5}>
            <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
              <InfoOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>Product Details</Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Product details</Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>
      <DialogContent
        sx={{
          display: 'grid',
          gridTemplateColumns: 'auto 10px auto',
          gap: 1,
          alignItems: 'center',
          px: 3,
          pt: 3,
          pb: 1,
        }}
      >
        {data ? (
          <>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              <strong>{t('product:title.code')}</strong>
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18, textAlign: 'center' }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
            >
              <strong>{data.code}</strong>
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('product:title.name')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center' }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.name.length > 14
                ? `${data.name.substring(0, 14)}...`
                : data.name}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('product:title.category')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.categoryName}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('product:title.unitPrice')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {getPriceFormat(data.unitPrice, currencyCode)}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('product:title.maxDisAmount')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {getPriceFormat(data.maxDiscountAmount, currencyCode)}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('product:title.stockAlertQty')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.stockAlertQty}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('product:title.reOrderQty')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.reOrderQty}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('product:title.defaultDiscountAmount')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {getPriceFormat(data.defaultDiscountAmount ?? 0, currencyCode)}{' '}
            </Typography>

            <>
              <Typography
                variant="body1"
                color="text.secondary"
                sx={{ fontSize: 18 }}
              >
                {t('product:title.expiryDate')}
              </Typography>
              <Typography
                variant="body1"
                color="text.secondary"
                sx={{ textAlign: 'center', fontSize: 18 }}
              >
                :
              </Typography>
              <Typography
                variant="body1"
                color="text.secondary"
                sx={{ fontSize: 18 }}
              >
                {data.expiryDate
                  ? formatDate(new Date(data.expiryDate))
                  : 'Not Available'}
              </Typography>
            </>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('product:title.isEnabled')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{
                fontSize: 18,
                color:
                  data.isEnabled === true
                    ? appColors.forestGreen[100]
                    : appColors.carmineRed[60],
              }}
            >
              {data.isEnabled ? 'Yes' : 'No'}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('product:title.isKgOrLitre')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{
                fontSize: 18,
                color: data.isKgOrLitre
                  ? appColors.forestGreen[100]
                  : appColors.carmineRed[60],
              }}
            >
              {data.isKgOrLitre ? 'Yes' : 'No'}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('product:title.isOnlineOrder')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{
                fontSize: 18,
                color: data.isOnlineOrder
                  ? appColors.forestGreen[100]
                  : appColors.carmineRed[60],
              }}
            >
              {data.isOnlineOrder ? 'Yes' : 'No'}
            </Typography>

            {data.createdBy && (
              <>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {t('product:title.createdBy')}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                >
                  :
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {data.createdBy}
                </Typography>
              </>
            )}
            {data.updatedBy && (
              <>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {t('product:title.updatedBy')}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                >
                  :
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {data.updatedBy}
                </Typography>
              </>
            )}
            {data.createdDate && (
              <>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {t('product:title.createdDate')}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                >
                  :
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {formatTimeToUtc(data.createdDate)}
                </Typography>
              </>
            )}
            {data.updatedDate && (
              <>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {t('product:title.updatedDate')}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                >
                  :
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {formatTimeToUtc(data.updatedDate)}
                </Typography>
              </>
            )}
          </>
        ) : (
          <Typography variant="body1">No product data available</Typography>
        )}
      </DialogContent>
      <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
        <Button
          onClick={handleClose}
          sx={{
            borderColor: '#CBD5E1',
            borderRadius: '8px',
            color: '#475569',
            fontWeight: 600,
            height: 40,
            minWidth: 110,
            px: 3,
            textTransform: 'none',
            '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
          }}
          variant="outlined"
        >
          Cancel
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default ProductListData;
